namespace _2026_web_api_01.Infrastructure.Data;

/// <summary>
/// Factory that creates <see cref="SqlConnection"/> instances using a connection string
/// loaded securely from an environment variable — never hardcoded in appsettings.json.
///
/// Environment variable name: DB_CONNECTION_STRING
///
/// How to set it (examples):
///   Windows (CMD):  setx DB_CONNECTION_STRING "Server=...;Database=...;User Id=...;Password=...;"
///   Windows (PS):   $env:DB_CONNECTION_STRING = "Server=...;Database=...;User Id=...;Password=...;"
///   Linux / macOS:  export DB_CONNECTION_STRING="Server=...;Database=...;User Id=...;Password=...;"
///   launchSettings.json (dev only — not checked into source control):
///     "environmentVariables": { "DB_CONNECTION_STRING": "Server=.;Database=MyDb;Trusted_Connection=True;TrustServerCertificate=True;" }
/// </summary>
public class DapperContext
{
    private readonly string _connectionString;

    public DapperContext()
    {
        // SECURELY load the connection string from an environment variable.
        // This keeps credentials out of source control and appsettings.json.
        var connStr = Environment.GetEnvironmentVariable("DB_CONNECTION_STRING")
                      ?? throw new InvalidOperationException(
                          "The environment variable 'DB_CONNECTION_STRING' is not set. " +
                          "Please configure it before running the application.");

        _connectionString = connStr;
    }

    /// <summary>
    /// Creates and returns a new <see cref="SqlConnection"/>.
    /// Callers must dispose the connection after use (typically via 'using').
    /// </summary>
    public IDbConnection CreateConnection()
    {
        return new SqlConnection(_connectionString);
    }
}

