namespace _2026_web_api_01.Services.Implementations;

/// <summary>
/// Product service with business-logic orchestration and entity-to-DTO mapping.
/// Depends only on the <see cref="IProductRepository"/> abstraction — not on the concrete
/// Dapper implementation — making it straightforward to mock in unit tests.
/// </summary>
public sealed class ProductService : IProductService
{
    private readonly IProductRepository _repository;

    public ProductService(IProductRepository repository)
    {
        _repository = repository;
    }

    /// <inheritdoc />
    public async Task<ProductDto?> GetProductByIdAsync(int id)
    {
        var entity = await _repository.GetByIdAsync(id);

        if (entity is null)
        {
            return null;
        }

        return MapToDto(entity);
    }

    /// <inheritdoc />
    public async Task<ProductDto> CreateProductAsync(CreateProductRequest request)
    {
        // Map the validated request to a domain entity.
        var entity = new ProductEntity
        {
            Name = request.Name,
            Description = request.Description,
            Price = request.Price,
            StockQuantity = request.StockQuantity,
            CreatedAt = DateTime.UtcNow,
        };

        var createdEntity = await _repository.CreateAsync(entity);

        return MapToDto(createdEntity);
    }

    private static ProductDto MapToDto(ProductEntity entity)
    {
        return new ProductDto(
            Id: entity.Id,
            Name: entity.Name,
            Description: entity.Description,
            Price: entity.Price,
            StockQuantity: entity.StockQuantity,
            CreatedAt: entity.CreatedAt
        );
    }
}

using Microsoft.AspNetCore.Mvc;
using _2026_web_api_01.Models.Requests;
using _2026_web_api_01.Services.Interfaces;

namespace _2026_web_api_01.API.Controllers;

[ApiController]
[Route("api/[controller]")]
public sealed class ProductController : ControllerBase
{
    private readonly IProductService _productService;

    public ProductController(IProductService productService)
    {
        _productService = productService;
    }

    /// <summary>
    /// GET /api/product/{id}
    /// Retrieves a product by its identifier.
    /// </summary>
    /// <param name="id">The product ID.</param>
    /// <returns>200 OK with the product DTO, or 404 Not Found.</returns>
    [HttpGet("{id:int}")]
    public async Task<IActionResult> GetById(int id)
    {
        var product = await _productService.GetProductByIdAsync(id);

        if (product is null)
        {
            return NotFound(new { Message = $"Product with ID {id} was not found." });
        }

        return Ok(product);
    }

    /// <summary>
    /// POST /api/product
    /// Creates a new product.
    /// </summary>
    /// <param name="request">The validated creation payload.</param>
    /// <returns>201 Created with the created product DTO, or 400 Bad Request on validation failure.</returns>
    [HttpPost]
    public async Task<IActionResult> Create([FromBody] CreateProductRequest request)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        var createdProduct = await _productService.CreateProductAsync(request);

        return CreatedAtAction(nameof(GetById), new { id = createdProduct.Id }, createdProduct);
    }
}

