using _2026_web_api_01.Infrastructure.Data;
using _2026_web_api_01.Models.Entities;

namespace _2026_web_api_01.Infrastructure.Repositories;

/// <summary>
/// Dapper implementation của <see cref="IInformationRepository"/>.
/// Toàn bộ truy vấn qua stored procedure với DynamicParameters để chống SQL Injection.
/// </summary>
public sealed class InformationRepository : IInformationRepository
{
    private readonly DapperContext _context;

    public InformationRepository(DapperContext context)
    {
        _context = context;
    }

    public async Task<IEnumerable<InfoInformationEntity>> GetAllAsync()
    {
        using var connection = _context.CreateConnection();

        var items = await connection.QueryAsync<InfoInformationEntity>(
            sql: "API_InfoInformation_GetAll",
            commandType: CommandType.StoredProcedure
        );

        return items;
    }

    public async Task<InfoInformationEntity?> GetByIdAsync(int id)
    {
        using var connection = _context.CreateConnection();

        var parameters = new DynamicParameters();
        parameters.Add("@InformationId", id);

        var item = await connection.QuerySingleOrDefaultAsync<InfoInformationEntity>(
            sql: "API_InfoInformation_GetById",
            param: parameters,
            commandType: CommandType.StoredProcedure
        );

        return item;
    }

    public async Task<InfoInformationEntity> CreateAsync(InfoInformationEntity entity)
    {
        using var connection = _context.CreateConnection();

        var parameters = new DynamicParameters();
        parameters.Add("@CategoryId", entity.CategoryId);
        parameters.Add("@Title", entity.Title);
        parameters.Add("@Summary", entity.Summary);
        parameters.Add("@Content", entity.Content);
        parameters.Add("@ImageUrl", entity.ImageUrl);

        var created = await connection.QuerySingleAsync<InfoInformationEntity>(
            sql: "API_InfoInformation_Create",
            param: parameters,
            commandType: CommandType.StoredProcedure
        );

        return created;
    }

    public async Task<InfoInformationEntity?> UpdateAsync(InfoInformationEntity entity)
    {
        using var connection = _context.CreateConnection();

        var parameters = new DynamicParameters();
        parameters.Add("@InformationId", entity.InformationId);
        parameters.Add("@CategoryId", entity.CategoryId);
        parameters.Add("@Title", entity.Title);
        parameters.Add("@Summary", entity.Summary);
        parameters.Add("@Content", entity.Content);
        parameters.Add("@ImageUrl", entity.ImageUrl);

        var updated = await connection.QuerySingleOrDefaultAsync<InfoInformationEntity>(
            sql: "API_InfoInformation_Update",
            param: parameters,
            commandType: CommandType.StoredProcedure
        );

        return updated;
    }

    public async Task<bool> DeleteAsync(int id)
    {
        using var connection = _context.CreateConnection();

        var parameters = new DynamicParameters();
        parameters.Add("@InformationId", id);

        var affectedRows = await connection.ExecuteAsync(
            sql: "API_InfoInformation_Delete",
            param: parameters,
            commandType: CommandType.StoredProcedure
        );

        return affectedRows > 0;
    }
}

