using Microsoft.AspNetCore.Mvc;
using _2026_web_api_01.Models.Requests;
using _2026_web_api_01.Services.Interfaces;

namespace _2026_web_api_01.API.Controllers;

[ApiController]
[Route("api/[controller]")]
public sealed class CategoryController : ControllerBase
{
    private readonly ICategoryService _categoryService;

    public CategoryController(ICategoryService categoryService)
    {
        _categoryService = categoryService;
    }

    /// <summary>
    /// GET /api/category
    /// Lấy danh sách tất cả danh mục đang hoạt động.
    /// </summary>
    /// <returns>200 OK với danh sách danh mục.</returns>
    [HttpGet]
    public async Task<IActionResult> GetAll()
    {
        var categories = await _categoryService.GetAllAsync();
        return Ok(categories);
    }

    /// <summary>
    /// GET /api/category/{id}
    /// Lấy 1 danh mục theo Id.
    /// </summary>
    /// <param name="id">CategoryId.</param>
    /// <returns>200 OK với danh mục, hoặc 404 Not Found.</returns>
    [HttpGet("{id:int}")]
    public async Task<IActionResult> GetById(int id)
    {
        var category = await _categoryService.GetByIdAsync(id);

        if (category is null)
        {
            return NotFound(new { Message = $"Category with ID {id} was not found." });
        }

        return Ok(category);
    }

    /// <summary>
    /// POST /api/category
    /// Tạo danh mục mới.
    /// </summary>
    /// <param name="request">Body: CategoryName (bắt buộc), Description (tuỳ chọn), SortOrder (tuỳ chọn).</param>
    /// <returns>201 Created với danh mục vừa tạo.</returns>
    [HttpPost]
    public async Task<IActionResult> Create([FromBody] CreateCategoryRequest request)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        var created = await _categoryService.CreateAsync(request);

        return CreatedAtAction(nameof(GetById), new { id = created.CategoryId }, created);
    }

    /// <summary>
    /// PUT /api/category/{id}
    /// Cập nhật danh mục.
    /// </summary>
    /// <param name="id">CategoryId cần cập nhật (trên URL).</param>
    /// <param name="request">Body: CategoryName, Description, SortOrder.</param>
    /// <returns>200 OK với danh mục đã cập nhật, hoặc 404 Not Found.</returns>
    [HttpPut("{id:int}")]
    public async Task<IActionResult> Update(int id, [FromBody] UpdateCategoryRequest request)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        var updated = await _categoryService.UpdateAsync(id, request);

        if (updated is null)
        {
            return NotFound(new { Message = $"Category with ID {id} was not found." });
        }

        return Ok(updated);
    }

    /// <summary>
    /// DELETE /api/category/{id}
    /// Xoá mềm danh mục (IsActive = 0).
    /// </summary>
    /// <param name="id">CategoryId.</param>
    /// <returns>200 OK nếu xoá thành công, hoặc 404 Not Found.</returns>
    [HttpDelete("{id:int}")]
    public async Task<IActionResult> Delete(int id)
    {
        var deleted = await _categoryService.DeleteAsync(id);

        if (!deleted)
        {
            return NotFound(new { Message = $"Category with ID {id} was not found or already deleted." });
        }

        return Ok(new { Message = $"Category with ID {id} has been deleted." });
    }
}

